**Plan, not yet applied.**

`buildRows()` already returns plain data, so `--json` just needs a branch in `[cli.js](src/cli.js)`:

```js
function main(argv) {
  const command = argv[0];
  if (command !== 'report') {
    process.stderr.write(USAGE + '\n');
    return 1;
  }
  const rows = buildRows();
  if (argv.includes('--json')) {
    process.stdout.write(JSON.stringify(rows) + '\n');
  } else {
    process.stdout.write(toTable(rows) + '\n');
  }
  return 0;
}
```

No changes needed in `report.js` or `format.js`.

